214	function imageUpload($path, $upfile, $origin_file = '', $return_origin = false)
215	{
216	    $allowed_ext = ['jpg', 'jpeg', 'png', 'gif', 'ico', 'svg'];
217	    $max_file_size = 10485760; // 10MB
218	
219	
220	
221	    // 빈값이거나 업로드 파일이 없을 경우 공백 반환
222	    if (empty($upfile) || !isset($upfile['name']) || $upfile['error'] === UPLOAD_ERR_NO_FILE) {
223	        return ['origin' => '', 'saved' => ''];
224	    }
225	
226	    try {
227	        // 파일 크기 제한 확인
228	        if ($upfile['size'] > $max_file_size) {
229	            throw new Exception("이미지 사이즈가 10MB 이하로 등록해주세요.");
230	        }
231	
232	        // 확장자 검증
233	        $ext = strtolower(pathinfo($upfile['name'], PATHINFO_EXTENSION));
234	        if (!in_array($ext, $allowed_ext)) {
235	            throw new Exception("허용되지 않는 파일입니다.");
236	        }
237	
238	        // 파일 이름 생성
239	        $file_saved = uniqid('', true) . ".$ext";
240	        $file_origin = $upfile['name'];
241	
242	        // 디렉터리 생성
243	        if (!is_dir($path) && !mkdir($path, 0755, true) && !is_dir($path)) {
244	            throw new Exception("파일 업로드 경로를 생성하지 못했습니다.");
245	        }
246	
247	        // echo json_encode(['files' => $_FILES, 'tmp' => $upfile['tmp_name'], 'path' => "$path/$file_saved"]); exit;
248	        // 파일 이동
249	        if (!move_uploaded_file($upfile['tmp_name'], "$path/$file_saved")) {
250	            throw new Exception("파일 업로드에 실패했습니다.");
251	        }
252	
253	        // 업로드된 이미지 옆에 .webp sibling 자동 생성 (큰 파일은 2560px 로 리사이즈)
254	        \Core\ImageProcessor::makeWebpSibling("$path/$file_saved");
255	
256	        // 기존 파일 삭제 (원본 + 동반 .webp sibling)
257	        if ($origin_file && file_exists("$path/$origin_file")) {
258	            \Core\ImageProcessor::deleteWebpSibling("$path/$origin_file");
259	            unlink("$path/$origin_file");
260	        }
261	
262	        // 결과 반환
263	        return $return_origin ? ['origin' => $file_origin, 'saved' => $file_saved] : ['origin' => '', 'saved' => $file_saved];
264	    } catch (Exception $e) {
265	        echo json_encode(["result" => "fail", "msg" => $e->getMessage()]);
266	        exit;
267	    }
268	}
