340	if (!function_exists('sanitize_html_fragment')) {
341	    function sanitize_html_fragment(string $html): string
342	    {
343	        if ($html === '') {
344	            return '';
345	        }
346	
347	        $allowed = '<p><br><b><strong><i><em><u><ul><ol><li><a><span><h1><h2><h3><h4><h5><h6>';
348	        $stripped = strip_tags($html, $allowed);
349	        $stripped = preg_replace('/\s*on\w+\s*=\s*("[^"]*"|\'[^\']*\')/i', '', $stripped) ?? $stripped;
350	        $stripped = preg_replace('/\s*javascript\s*:/i', '', $stripped) ?? $stripped;
351	
352	        return $stripped;
353	    }
