143	    public function getList(int $offset, int $limit, ?string $category = null): array
144	    {
145	        $normalizedOffset = max(0, $offset);
146	        $normalizedLimit = max(1, min(self::MAX_LIMIT, $limit));
147	        $rows = $this->selectRows($normalizedOffset, $normalizedLimit + 1, $category);
148	        $hasMore = count($rows) > $normalizedLimit;
