240	    /**
241	     * @return array<int, array<string, mixed>>
242	     */
243	    private function selectRows(int $offset, int $limit, ?string $category): array
244	    {
245	        $conditions = [
246	            '`is_visible` = :is_visible',
247	            '`deleted_at` IS NULL',
248	        ];
249	        $bindings = [
250	            ':is_visible' => [self::VISIBLE_VALUE, \PDO::PARAM_INT],
251	        ];
252	
253	        $resolvedCategory = $this->resolveCategory($category);
254	        if ($resolvedCategory !== null) {
255	            $categoryId = $this->resolveCategoryId($resolvedCategory);
256	            if ($categoryId === null) {
257	                return [];
258	            }
259	
260	            $conditions[] = 'JSON_CONTAINS(`category`, CAST(:category_json AS JSON))';
261	            $bindings[':category_json'] = [(string) $categoryId, \PDO::PARAM_STR];
262	        }
263	
264	        $whereClause = 'WHERE ' . implode(' AND ', $conditions);
265	        $sql = <<<SQL
266	SELECT
267	    `id`,
268	    `title`,
269	    `thumb_image`,
270	    `video`,
271	    `client`,
272	    `category`,
273	    `tag`,
274	    `updated_at`,
275	    `created_at`,
276	    `file_attach1`,
277	    `file_attach2`,
278	    `file_attach3`,
279	    `file_attach4`,
280	    `file_attach5`
281	FROM `nb_works`
282	{$whereClause}
283	ORDER BY `sort_no` DESC, `id` DESC
284	LIMIT :limit OFFSET :offset
285	SQL;
286	
287	        $statement = $this->pdo->prepare($sql);
288	        foreach ($bindings as $name => [$value, $type]) {
289	            $statement->bindValue($name, $value, $type);
290	        }
291	        $statement->bindValue(':limit', $limit, \PDO::PARAM_INT);
292	        $statement->bindValue(':offset', $offset, \PDO::PARAM_INT);
293	        $statement->execute();
294	
295	        $rows = $statement->fetchAll();
296	        return is_array($rows) ? $rows : [];
297	    }
