556	    private function resolveVideoUrl($rawValue): ?string
557	    {
558	        $decoded = $this->decodeJsonValue($rawValue);
559	
560	        if (is_string($decoded)) {
561	            return $this->normalizeAssetOrUrl($decoded);
562	        }
563	
564	        if (!is_array($decoded)) {
565	            return null;
566	        }
567	
568	        foreach ($decoded as $value) {
569	            if (!is_string($value)) {
570	                continue;
571	            }
572	
573	            $url = $this->normalizeAssetOrUrl($value);
574	            if ($url === null) {
575	                continue;
576	            }
577	
578	            return $url;
579	        }
580	
581	        return null;
582	    }
