628	    /**
629	     * @return array<int, int>
630	     */
631	    private function normalizeIntegerList($value): array
632	    {
633	        $decoded = $this->decodeJsonValue($value);
634	        if (is_int($decoded)) {
635	            return [$decoded];
636	        }
637	
638	        if (is_string($decoded) && preg_match('/^\d+$/', $decoded) === 1) {
639	            return [(int) $decoded];
640	        }
641	
642	        if (!is_array($decoded)) {
643	            return [];
644	        }
645	
646	        $items = [];
647	        foreach ($decoded as $item) {
648	            if (is_int($item)) {
649	                $items[] = $item;
650	                continue;
651	            }
652	
653	            if (!is_string($item) || preg_match('/^\d+$/', $item) !== 1) {
654	                continue;
655	            }
656	
657	            $items[] = (int) $item;
658	        }
659	
660	        return array_values(array_unique($items));
661	    }
662	
663	    /**
664	     * @return array<int, string>
665	     */
666	    private function normalizeStringList($value): array
667	    {
668	        $decoded = $this->decodeJsonValue($value);
669	        if (is_string($decoded)) {
670	            $normalized = trim($decoded, " \t\n\r\0\x0B\"'");
671	            return $normalized === '' ? [] : [$normalized];
672	        }
673	
674	        if (!is_array($decoded)) {
675	            return [];
676	        }
677	
678	        $items = [];
679	        foreach ($decoded as $item) {
680	            if (!is_string($item)) {
681	                continue;
682	            }
683	
684	            $normalized = trim($item);
685	            if ($normalized === '') {
686	                continue;
687	            }
688	
689	            $items[] = $normalized;
690	        }
691	
692	        return array_values(array_unique($items));
693	    }
694	
695	    private function decodeJsonValue($value)
696	    {
697	        if (is_array($value) || is_int($value)) {
698	            return $value;
699	        }
700	
701	        if (!is_string($value)) {
702	            return null;
703	        }
704	
705	        $normalized = trim($value);
706	        if ($normalized === '') {
707	            return null;
708	        }
709	
710	        $decoded = json_decode($normalized, true);
711	        if (json_last_error() === JSON_ERROR_NONE) {
712	            return $decoded;
713	        }
714	
715	        return $normalized;
716	    }
717	
718	    private function buildAssetUrl($value): ?string
719	    {
720	        $filename = trim((string) $value);
721	        if ($filename === '') {
722	            return null;
723	        }
724	
725	        if ($this->isExternalUrl($filename)) {
726	            return $filename;
727	        }
728	
729	        if (strpos($filename, '/') === 0) {
730	            return base_path($filename);
731	        }
732	
733	        return base_path(self::WORKS_UPLOAD_PATH . '/' . rawurlencode($filename));
734	    }
735	
736	    private function isExternalUrl(string $value): bool
737	    {
738	        return preg_match('#^(https?:)?//#i', $value) === 1;
739	    }
740	
741	    private function formatDate($value): ?string
742	    {
743	        $dateValue = trim((string) $value);
744	        if ($dateValue === '') {
745	            return null;
746	        }
747	
748	        $timestamp = strtotime($dateValue);
749	        if ($timestamp === false) {
750	            return null;
751	        }
752	
753	        return date('Y.m.d', $timestamp);
