756	    /**
757	     * AWARDS 페이지용: 노출 중이고 수상 처리된 nb_works 행.
758	     *
759	     * @return list<array{
760	     *   year: string,
761	     *   title: string,
762	     *   awardLabel: string,
763	     *   awardIcon: ?string,
764	     *   prize: string,
765	     *   detailPath: string,
766	     *   previewImage: string
767	     * }>
768	     */
769	    public function getAwardPageRows(): array
770	    {
771	        $sql = <<<'SQL'
772	SELECT
773	    `id`,
774	    `title`,
775	    `is_awarded`,
776	    `award_type`,
777	    `award_detail`,
778	    `thumb_image`,
779	    `video`,
780	    `created_at`
781	FROM `nb_works`
782	WHERE `deleted_at` IS NULL
783	  AND `is_visible` = :visible
784	  AND UPPER(TRIM(`is_awarded`)) = 'Y'
785	  AND `award_type` IS NOT NULL
786	  AND `award_type` > 0
787	ORDER BY `created_at` DESC, `id` DESC
788	SQL;
789	        $statement = $this->pdo->prepare($sql);
790	        $statement->bindValue(':visible', self::VISIBLE_VALUE, \PDO::PARAM_INT);
791	        $statement->execute();
792	        $rows = $statement->fetchAll();
793	        if (!is_array($rows)) {
794	            return [];
795	        }
796	        $out = [];
797	        foreach ($rows as $row) {
798	            if (!is_array($row)) {
799	                continue;
800	            }
801	            $award = $this->resolveAward(
802	                $row['is_awarded'] ?? null,
803	                $row['award_type'] ?? null,
804	                $row['award_detail'] ?? null
805	            );
806	            if ($award === null) {
807	                continue;
808	            }
809	            $created = $row['created_at'] ?? null;
810	            $year = '';
811	            if ($created !== null && (string) $created !== '') {
812	                $ts = strtotime((string) $created);
813	                if ($ts !== false) {
814	                    $year = date('Y', $ts);
815	                }
816	            }
817	            $detail = $award['detail'] ?? '';
818	            $prize = $detail !== null && $detail !== '' ? $detail : '';
819	            $out[] = [
820	                'year' => $year,
821	                'title' => $this->normalizeText($row['title'] ?? null) ?? '',
822	                'awardLabel' => $award['label'],
823	                'awardIcon' => $award['icon'],
824	                'prize' => $prize,
825	                'detailPath' => '/works/view/' . rawurlencode((string) ($row['id'] ?? '')),
826	                'previewImage' => $this->resolveThumbnailImage($row),
827	            ];
828	        }
829	
830	        return $out;
831	    }
832	}
