210	  }
211	
212	  beginDrag(camera: THREE.Camera, pointer: WorksPointerSample): void {
213	    this._isDragging = true;
214	    this._dragPrevious = { ...pointer };
215	    this._velocityX = 0;
216	    this._velocityY = 0;
217	    this._targetX = camera.position.x;
218	    this._targetY = camera.position.y;
219	  }
220	
221	  endDrag(): void {
222	    this._isDragging = false;
223	  }
224	
225	  updateDrag(
226	    viewport: WorksViewportSnapshot,
227	    halfView: WorksHalfViewBounds,
228	    pointer: WorksPointerSample,
229	  ): void {
230	    if (!this._isDragging) return;
231	    const dx = pointer.x - this._dragPrevious.x;
232	    const dy = pointer.y - this._dragPrevious.y;
233	    this._targetX += (-dx * (halfView.hW * 2)) / viewport.width;
234	    this._targetY += (dy * (halfView.hH * 2)) / viewport.height;
235	    this._velocityX = ((-dx * (halfView.hW * 2)) / viewport.width) * 0.7;
236	    this._velocityY = ((dy * (halfView.hH * 2)) / viewport.height) * 0.7;
237	    this._targetX = Math.max(
238	      this._dynClampMinX + halfView.hW,
239	      Math.min(this._dynClampMaxX - halfView.hW, this._targetX),
240	    );
241	    this._targetY = Math.max(
242	      this._dynClampMinY + halfView.hH,
243	      Math.min(this._dynClampMaxY - halfView.hH, this._targetY),
244	    );
245	    this._dragPrevious = { ...pointer };
246	  }
247	
248	  updateFrame(camera: THREE.Camera, delta: number): void {
249	    if (this._isDragging) {
250	      const decay = Math.pow(this._layout.velDecay, delta * 60);
251	      this._velocityX *= decay;
252	      this._velocityY *= decay;
253	      this._targetX += this._velocityX * delta * 60;
254	      this._targetY += this._velocityY * delta * 60;
255	    }
256	    const camFactor = 1 - Math.pow(1 - this._layout.camLerp, delta * 60);
257	    camera.position.x += (this._targetX - camera.position.x) * camFactor;
258	    camera.position.y += (this._targetY - camera.position.y) * camFactor;
259	    const camZFactor = 1 - Math.pow(1 - this._layout.camZLerp, delta * 60);
260	    camera.position.z += (this._targetZ - camera.position.z) * camZFactor;
261	    camera.lookAt(camera.position.x, camera.position.y, 0);
262	  }
263	
264	  get isDragging(): boolean {
265	    return this._isDragging;
266	  }
