110	class WorksProjectsLoader {
111	  private _fetchAbortController: AbortController | null = null;
112	
113	  async load(state: WorksPageState): Promise<WorkProjectItem[]> {
114	    this._fetchAbortController?.abort();
115	    this._fetchAbortController = new AbortController();
116	    const signal = this._fetchAbortController.signal;
117	    const projects: WorkProjectItem[] = [];
118	    let offset = 0;
119	    let hasMore = true;
120	
121	    while (hasMore && projects.length < WORK_CANVAS_CONFIG.totalCards) {
122	      const remaining = WORK_CANVAS_CONFIG.totalCards - projects.length;
123	      const response = await fetchWorksList(
124	        offset,
125	        Math.min(WORKS_LIST_API_MAX_LIMIT, remaining),
126	        state.category,
127	        signal,
128	      );
129	      response.items.forEach((item, index) => {
130	        projects.push(createWorkProjectItem(item, projects.length + index));
131	      });
132	      hasMore = response.hasMore;
133	      offset = response.nextOffset ?? offset + response.items.length;
134	      if (response.items.length === 0) {
135	        hasMore = false;
136	      }
137	    }
138	
139	    this._fetchAbortController = null;
140	    return projects;
141	  }
142	
143	  isAbortedError(error: unknown): boolean {
144	    return error instanceof DOMException && error.name === "AbortError";
145	  }
146	
147	  dispose(): void {
148	    this._fetchAbortController?.abort();
149	    this._fetchAbortController = null;
150	  }
