106	function drawImageCover(
107	  ctx: CanvasRenderingContext2D,
108	  image: HTMLImageElement,
109	  width: number,
110	  imageHeight: number,
111	): void {
112	  const ratio = width / imageHeight;
113	  const imageRatio = image.naturalWidth / image.naturalHeight;
114	  let sw: number;
115	  let sh: number;
116	  let sx: number;
117	  let sy: number;
118	  if (imageRatio > ratio) {
119	    sh = image.naturalHeight;
120	    sw = image.naturalHeight * ratio;
121	    sx = (image.naturalWidth - sw) / 2;
122	    sy = 0;
123	  } else {
124	    sw = image.naturalWidth;
125	    sh = image.naturalWidth / ratio;
126	    sx = 0;
127	    sy = (image.naturalHeight - sh) / 2;
128	  }
129	  ctx.drawImage(image, sx, sy, sw, sh, 0, 0, width, imageHeight);
130	}
131	
132	function drawCardToContext(
133	  ctx: CanvasRenderingContext2D,
134	  proj: WorkProjectItem,
135	  size: WorkCardSize,
136	  image?: HTMLImageElement | null,
137	  renderOptions: WorkCardRenderOptions = WORK_CARD_DEFAULT_RENDER_OPTIONS,
138	): void {
139	  const width = CANVAS_W;
140	  const height = Math.round((width * size.h) / size.w);
141	  const imageHeight = Math.round(width / IMAGE_ASPECT);
142	
143	  ctx.save();
144	  ctx.translate(0, height);
145	  ctx.scale(1, -1);
146	
147	  if (image && image.complete && image.naturalWidth > 0) {
148	    drawImageCover(ctx, image, width, imageHeight);
149	  } else {
150	    const gradient = ctx.createLinearGradient(0, 0, width, imageHeight);
151	    gradient.addColorStop(0, proj.bg);
152	    gradient.addColorStop(1, Helpers.lightenHex(proj.bg, 18));
153	    ctx.fillStyle = gradient;
154	    ctx.fillRect(0, 0, width, imageHeight);
155	    for (let index = 0; index < 6000; index += 1) {
156	      ctx.fillStyle = `rgba(255,255,255,${Math.random() * 0.04})`;
157	      ctx.fillRect(Math.random() * width, Math.random() * imageHeight, 1, 1);
158	    }
159	    const radial = ctx.createRadialGradient(
160	      width * 0.25,
161	      imageHeight * 0.2,
162	      0,
163	      width * 0.25,
164	      imageHeight * 0.2,
165	      width * 0.8,
166	    );
167	    radial.addColorStop(0, Helpers.hexToRgba(proj.ac, 0.28));
168	    radial.addColorStop(1, "rgba(0,0,0,0)");
169	    ctx.fillStyle = radial;
170	    ctx.fillRect(0, 0, width, imageHeight);
171	  }
172	
173	  drawTitleBar(ctx, proj, width, imageHeight, renderOptions);
174	  ctx.restore();
175	}
