177	export class WorkCard {
178	  static buildTexture(
179	    proj: WorkProjectItem,
180	    size: WorkCardSize,
181	    image?: HTMLImageElement | null,
182	    renderOptions: WorkCardRenderOptions = WORK_CARD_DEFAULT_RENDER_OPTIONS,
183	  ): THREE.CanvasTexture {
184	    const key = `${proj.title}_${proj.category}_${size.w}_${size.h}_${renderOptions.showCategory ? "category" : "title"}_${renderOptions.showViewModal ? "modal" : "plain"}`;
185	    const cached = texCache.get(key);
186	    if (cached) return cached;
187	
188	    const width = CANVAS_W;
189	    const height = Math.round((width * size.h) / size.w);
190	    const canvas = document.createElement("canvas");
191	    canvas.width = width * CANVAS_DPI_SCALE;
192	    canvas.height = height * CANVAS_DPI_SCALE;
193	    const ctx = canvas.getContext("2d");
194	    if (!ctx) throw new Error("Canvas 2d context unavailable");
195	    ctx.imageSmoothingEnabled = true;
196	    ctx.imageSmoothingQuality = "high";
197	    ctx.setTransform(CANVAS_DPI_SCALE, 0, 0, CANVAS_DPI_SCALE, 0, 0);
198	
199	    drawCardToContext(ctx, proj, size, image, renderOptions);
200	
201	    const texture = new THREE.CanvasTexture(canvas);
202	    texture.flipY = false;
203	    texture.premultiplyAlpha = false;
204	    texture.anisotropy = 16;
205	    texCache.set(key, texture);
206	    return texture;
207	  }
208	
209	  static updateTextureImage(
210	    texture: THREE.CanvasTexture,
211	    proj: WorkProjectItem,
212	    size: WorkCardSize,
213	    image: HTMLImageElement,
214	    renderOptions: WorkCardRenderOptions = WORK_CARD_DEFAULT_RENDER_OPTIONS,
215	  ): void {
216	    const canvas = texture.image as HTMLCanvasElement;
217	    if (!canvas || !(canvas.getContext instanceof Function)) return;
218	    const ctx = canvas.getContext("2d");
219	    if (!ctx) return;
220	    const scale = canvas.width / CANVAS_W;
221	    ctx.setTransform(1, 0, 0, 1, 0, 0);
222	    ctx.clearRect(0, 0, canvas.width, canvas.height);
223	    ctx.setTransform(scale, 0, 0, scale, 0, 0);
224	    drawCardToContext(ctx, proj, size, image, renderOptions);
225	    texture.needsUpdate = true;
226	  }
