229	    texture: THREE.CanvasTexture,
230	    proj: WorkProjectItem,
231	    size: WorkCardSize,
232	    image: HTMLImageElement | null,
233	    renderOptions: WorkCardRenderOptions,
234	  ): void {
235	    const canvas = texture.image as HTMLCanvasElement;
236	    if (!canvas || !(canvas.getContext instanceof Function)) return;
237	    const ctx = canvas.getContext("2d");
238	    if (!ctx) return;
239	    const scale = canvas.width / CANVAS_W;
240	    ctx.setTransform(1, 0, 0, 1, 0, 0);
241	    ctx.clearRect(0, 0, canvas.width, canvas.height);
242	    ctx.setTransform(scale, 0, 0, scale, 0, 0);
